               (js/core/auth-boot.js): identity only from GET /api/auth/me, and no
               local business state.
   It is a source constant and nothing else: it is never inferred from the hostname,
   the URL, a cookie, storage, a query parameter or whether the backend answers, and
   there is no automatic fallback between the modes. The shipped value stays LOCAL
   until the AFI-5 mode flip. Any other value fails closed (no identity, no state). */
const AUTH_MODES = Object.freeze({ LOCAL: 'local', SESSION: 'session' });
const AUTH_MODE = AUTH_MODES.LOCAL;

/* ---------- transaction lifecycle ---------- */
const STATUS = {
